package palindrome

import (
	"errors"
	"strconv"
)

// Product stores a palindromic product value and all of its
// factorizations (pairs of factors) within the given range.
type Product struct {
	Value          int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic products of
// two numbers in the range [fmin, fmax] (both inclusive), along
// with all factor pairs of each within the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if min.Value == 0 || product < min.Value {
				min = Product{product, [][2]int{{i, j}}}
			} else if product == min.Value {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if product > max.Value {
				max = Product{product, [][2]int{{i, j}}}
			} else if product == max.Value {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if min.Value == 0 {
		return Product{}, Product{}, errors.New("no palindromes")
	}

	return min, max, nil
}

// isPalindrome reports whether i reads the same forwards and backwards.
func isPalindrome(i int) bool {
	s := strconv.Itoa(i)
	for l, r := 0, len(s)-1; l < r; l, r = l+1, r-1 {
		if s[l] != s[r] {
			return false
		}
	}
	return true
}
